/**
 * این فایل خودکار توسط tools/build_pack/build-pack.ts ساخته می‌شود.
 * بستهٔ پاسخ کوچک (داخل APK): intent + slots بدون هیچ مبلغ.
 * manifest: {"format":1,"version":"1.0.0","count":6035,"bytes":276962,"checksum":"3e5ce168","builtFrom":"corpus.jsonl (dataset + synthetic)","syntheticShare":0.977,"keysAreMasked":true,"storesMoney":false}
 */
import { bytesFromBase64, openPack, type PackIndex } from "../pack";

export const SMALL_PACK_MANIFEST = {
  "format": 1,
  "version": "1.0.0",
  "count": 6035,
  "bytes": 276962,
  "checksum": "3e5ce168",
  "builtFrom": "corpus.jsonl (dataset + synthetic)",
  "syntheticShare": 0.977,
  "keysAreMasked": true,
  "storesMoney": false
} as const;

const BASE64 =
  "";

let index: PackIndex | null = null;

export function smallPack(): PackIndex {
  if (!index) index = openPack(bytesFromBase64(BASE64), SMALL_PACK_MANIFEST);
  return index;
}
